import { Button, Typography } from '@mui/material'
import { Meta, StoryObj } from '@storybook/react'
import { useState } from 'react'

import RcSesDialog from '@/components/overlays/Dialog'

const meta: Meta<typeof RcSesDialog> = {
  component: RcSesDialog,
  title: 'components/overlays/Dialog',
  parameters: {
    layout: 'centered',
  },
  tags: ['autodocs'],
}

export default meta
type Story = StoryObj<typeof RcSesDialog>

function DialogStory({
  dialogTitle,
  size,
  children,
}: {
  dialogTitle: string
  size?: 'sm' | 'md' | 'lg'
  children: React.ReactNode
}) {
  const [open, setOpen] = useState(false)

  return (
    <>
      <Button onClick={() => setOpen(true)} variant='contained'>
        Open Dialog
      </Button>
      <RcSesDialog
        open={open}
        onClose={() => setOpen(false)}
        dialogTitle={dialogTitle}
        size={size}
        actions={
          <>
            <Button onClick={() => setOpen(false)} color='inherit'>
              Cancel
            </Button>
            <Button onClick={() => setOpen(false)} variant='contained'>
              Confirm
            </Button>
          </>
        }
      >
        {children}
      </RcSesDialog>
    </>
  )
}

export const Basic: Story = {
  render: () => (
    <DialogStory dialogTitle='Confirm Action'>
      <Typography>Are you sure you want to proceed?</Typography>
    </DialogStory>
  ),
}

export const SmallDialog: Story = {
  render: () => (
    <DialogStory dialogTitle='Small Dialog' size='sm'>
      <Typography>
        This is a <b>small</b> dialog (480px width).
      </Typography>
    </DialogStory>
  ),
  parameters: {
    docs: {
      description: {
        story: 'Small size dialog (480px width).',
      },
    },
  },
}

